package sourcepos

import (
	"bufio"
	"os"
	"strconv"
	"strings"
	"testing"
)

// The NFC of Glose against that of Python (Unicode tables of the same
// version), on 3 000 strings rich in combining marks, jamo, characters that
// NFC splits or excludes from composition (testdata/nfc.txt, generated by
// tools/gen-nfc/gen.py --vectors).
func TestNFCAgainstPython(t *testing.T) {
	f, err := os.Open("testdata/nfc.txt")
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	parse := func(s string) []rune {
		var out []rune
		for _, h := range strings.Fields(s) {
			v, err := strconv.ParseUint(h, 16, 32)
			if err != nil {
				t.Fatal(err)
			}
			out = append(out, rune(v))
		}
		return out
	}
	sc := bufio.NewScanner(f)
	n := 0
	for sc.Scan() {
		in, want, _ := strings.Cut(sc.Text(), "\t")
		got := nfc(parse(in))
		if string(got) != string(parse(want)) {
			t.Errorf("NFC(%q) = %q, attendu %q", string(parse(in)), string(got), string(parse(want)))
		}
		n++
	}
	if n < 3000 {
		t.Fatalf("seulement %d vecteurs", n)
	}
}

func TestNFCBoundary(t *testing.T) {
	for r, want := range map[rune]bool{'a': true, ' ': true, 'é': true, 0x0301: false, 0x0958: true, 0x0F73: false, 0x1161: false, 0xAC00: true, 0x0B3E: false, 0x2764: true, 0x10FFFD: true, 0x0378: false, 0x212B: true} {
		if got := nfcBoundary(r); got != want {
			t.Errorf("nfcBoundary(%U) = %v, attendu %v", r, got, want)
		}
	}
}

// FuzzNFCPieces: normalising a text piece by piece, cut before the
// boundaries of nfcBoundary, gives its NFC: the property the index relies on.
func FuzzNFCPieces(f *testing.F) {
	f.Add([]byte{0, 1, 2, 3, 4, 5, 6, 7})
	pool := []rune{'a', 'e', 'o', ' ', 'A', 0x3B1, 0x915, 0x958, 0x93C, 0x94D, 0xB47, 0xB3E, 0xB57, 0x1100, 0x1161,
		0x11A8, 0xAC00, 0xAC01, 0x300, 0x301, 0x302, 0x308, 0x323, 0x327, 0x345, 0x5B0, 0x5B7, 0x5BC, 0x5D0, 0x5C1,
		0xE9, 0x212B, 0x2126, 0x30AB, 0x3099, 0x0F71, 0x0F72, 0x0F73, 0x0F80, 0x0F40, 0x1D15E, 0x1D165, 0x0378, 0x0344}
	f.Fuzz(func(t *testing.T, b []byte) {
		var s []rune
		for _, c := range b {
			s = append(s, pool[int(c)%len(pool)])
		}
		var pieces []rune
		start := 0
		for i := 1; i <= len(s); i++ {
			if i == len(s) || nfcBoundary(s[i]) {
				pieces = append(pieces, nfc(s[start:i])...)
				start = i
			}
		}
		if whole := nfc(s); string(whole) != string(pieces) {
			t.Fatalf("%q : par morceaux %q, d'un coup %q", string(s), string(pieces), string(whole))
		}
	})
}
